def pairopts(a,b,ta=(0,0), rangev=12):
 A=pieces[a]; B=pieces[b]; pa={(r+ta[0],c+ta[1]) for r,c in A['p']}; ma={(r+ta[0],c+ta[1]) for r,c in A['m']}
 out=[]
 for dr in range(-rangev,rangev+1):
  for dc in range(-rangev,rangev+1):
   pb={(r+dr,c+dc) for r,c in B['p']}; mb={(r+dr,c+dc) for r,c in B['m']}
   if pb & (pa|ma) or mb&(pa|ma): continue
   # marker pixel adjacency pair list
   contactA=[m for m in ma if any((m[0]+rr,m[1]+cc) in pb for rr,cc in [(1,0),(-1,0),(0,1),(0,-1)])]
   contactB=[m for m in mb if any((m[0]+rr,m[1]+cc) in pa for rr,cc in [(1,0),(-1,0),(0,1),(0,-1)])]
   score=len(contactA)+len(contactB)
   if score>=2: out.append((score,dr,dc,len(contactA),len(contactB),contactA,contactB))
 return sorted(out,reverse=True)
